async function getAppFunnel({ property, from, to, ingest = null }) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const ingestPath = normalizeIngest(ingest);

  const stages = [
    'onboarding_enter',
    'onboarding_complete',
    'signin_view',
    'signin_attempt',
    'signin_success',
    'signup_view',
    'signup_attempt',
    'signup_success',
  ];

  const cacheKey = `admin:analytics:app:funnel::${normalizedProperty}::${ingestPath || 'all'}::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    const schema = await getAnalyticsEventsSchema();
    if (!schema.exists) throwAnalyticsSchemaError();
    const expr = buildAnalyticsEventsExpr(schema.columns);

    const result = await query(
      `WITH base AS (
        SELECT
          event_type,
          ${expr.sessionIdExpr} AS session_id
        FROM public.analytics_events
        WHERE event_category = 'app'
          AND ${expr.propertyExpr} = $1
          AND event_type = ANY($5::text[])
          AND ${expr.tsExpr} >= $2::timestamptz
          AND ${expr.tsExpr} <= $3::timestamptz
          AND ($4::text IS NULL OR ${expr.ingestPathExpr} = $4)
          AND ${expr.eventIdExpr} IS NOT NULL
          AND ${expr.sessionIdExpr} IS NOT NULL
      )
      SELECT
        COUNT(*) FILTER (WHERE event_type = 'onboarding_enter')::int AS onboarding_enter_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'onboarding_enter')::int AS onboarding_enter_sessions,
        COUNT(*) FILTER (WHERE event_type = 'onboarding_complete')::int AS onboarding_complete_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'onboarding_complete')::int AS onboarding_complete_sessions,

        COUNT(*) FILTER (WHERE event_type = 'signin_view')::int AS signin_view_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'signin_view')::int AS signin_view_sessions,
        COUNT(*) FILTER (WHERE event_type = 'signin_attempt')::int AS signin_attempt_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'signin_attempt')::int AS signin_attempt_sessions,
        COUNT(*) FILTER (WHERE event_type = 'signin_success')::int AS signin_success_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'signin_success')::int AS signin_success_sessions,

        COUNT(*) FILTER (WHERE event_type = 'signup_view')::int AS signup_view_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'signup_view')::int AS signup_view_sessions,
        COUNT(*) FILTER (WHERE event_type = 'signup_attempt')::int AS signup_attempt_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'signup_attempt')::int AS signup_attempt_sessions,
        COUNT(*) FILTER (WHERE event_type = 'signup_success')::int AS signup_success_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'signup_success')::int AS signup_success_sessions
      FROM base`,
      [normalizedProperty, range.from.toISOString(), range.to.toISOString(), ingestPath, stages],
    );

    const row = result.rows[0] || {};

    const perStage = {};
    for (const stage of stages) {
      perStage[stage] = {
        events: Number(row[`${stage}_events`] || 0),
        sessions: Number(row[`${stage}_sessions`] || 0),
      };
    }

    return {
      property: normalizedProperty,
      from: range.from.toISOString(),
      to: range.to.toISOString(),
      stages: perStage,
    };
  }, { ttlSeconds: 60 });
}

/// Ordered stages of the guest -> account activation funnel.
///
/// Each stage is measured by distinct `session_id`, because that is the unit a
/// visitor actually is: one person arriving from an ad, browsing, and either
/// activating or not. Event counts are returned alongside so a stage that fires
/// repeatedly (a visitor who opens several artworks) is still legible.
const ACTIVATION_FUNNEL_STAGES = [
  'guest_app_loaded',
  'map_opened',
  'artwork_viewed',
  'protected_action_clicked',
  'auth_gate_viewed',
  'registration_submitted',
  'account_session_created',
  'pending_action_restored',
  'pending_action_completed',
];

/// Direct-acquisition stages: an ad that links straight to `/register`.
///
/// These visitors never touch the guest map, so they emit none of the
/// discovery stages above and scored zero on that funnel — their entry was
/// literally not counted. Every stage here is an event the client already
/// emits; `app_entry` is the one addition, fired once per session on any entry
/// route so this funnel has a denominator at all.
const DIRECT_ACQUISITION_FUNNEL_STAGES = [
  'app_entry',
  'signup_view',
  'signup_attempt',
  'registration_submitted',
  'account_session_created',
  'onboarding_complete',
  'contribution_started',
  'contribution_submitted',
];

/// The two funnels this endpoint can report.
///
/// They deliberately do not share a stage list: forcing organic map-first
/// discovery and direct-to-register paid traffic through one sequence makes
/// both unreadable. `guest_discovery` is the original funnel, unchanged, and
/// stays the default so existing callers keep their exact response.
///
/// `entryStage` is the funnel's denominator, `registeredStage` the account
/// milestone, `onboardedStage` the setup milestone, and `activatedStage` the
/// meaningful-action milestone. A page view or a login is never an activation.
const ACTIVATION_FUNNELS = {
  guest_discovery: {
    stages: ACTIVATION_FUNNEL_STAGES,
    entryStage: 'guest_app_loaded',
    registeredStage: 'account_session_created',
    onboardedStage: null,
    activatedStage: 'pending_action_completed',
    // Median transitions reported for this funnel, in response-key order.
    // [responseKey, sqlAlias, fromStage, toStage]
    durations: [
      ['mapToProtectedAction', 'map_to_protected_action_seconds', 'map_opened', 'protected_action_clicked'],
      ['protectedActionToSession', 'protected_action_to_session_seconds', 'protected_action_clicked', 'account_session_created'],
      ['sessionToActionCompleted', 'session_to_action_completed_seconds', 'account_session_created', 'pending_action_completed'],
    ],
    // Legacy per-dimension columns, preserved verbatim for existing dashboards.
    // [responseKey, sqlAlias, stage]
    breakdownStages: [
      ['guestSessions', 'guest_sessions', 'guest_app_loaded'],
      ['mapSessions', 'map_sessions', 'map_opened'],
      ['protectedActionSessions', 'protected_action_sessions', 'protected_action_clicked'],
      ['activatedSessions', 'activated_sessions', 'account_session_created'],
      ['completedSessions', 'completed_sessions', 'pending_action_completed'],
    ],
    // Denominator for the per-dimension activation rate.
    breakdownRateBase: 'mapSessions',
  },
  direct_acquisition: {
    stages: DIRECT_ACQUISITION_FUNNEL_STAGES,
    entryStage: 'app_entry',
    registeredStage: 'account_session_created',
    onboardedStage: 'onboarding_complete',
    activatedStage: 'contribution_submitted',
    durations: [
      ['entryToSignupView', 'entry_to_signup_view_seconds', 'app_entry', 'signup_view'],
      ['signupViewToSession', 'signup_view_to_session_seconds', 'signup_view', 'account_session_created'],
      ['sessionToContribution', 'session_to_contribution_seconds', 'account_session_created', 'contribution_submitted'],
    ],
    breakdownStages: [
      ['entrySessions', 'entry_sessions', 'app_entry'],
      ['signupViewSessions', 'signup_view_sessions', 'signup_view'],
      ['registeredSessions', 'registered_sessions', 'account_session_created'],
      ['onboardedSessions', 'onboarded_sessions', 'onboarding_complete'],
      ['activatedSessions', 'activated_sessions', 'contribution_submitted'],
    ],
    breakdownRateBase: 'entrySessions',
  },
};

const ACTIVATION_FUNNEL_KEYS = Object.freeze(Object.keys(ACTIVATION_FUNNELS));
const DEFAULT_ACTIVATION_FUNNEL = 'guest_discovery';

/// An unrecognised funnel falls back to the default rather than erroring, for
/// the same reason an unrecognised breakdown does: a stale dashboard link
/// should still render.
function normalizeActivationFunnel(value) {
  const key = (value || '').toString().trim().toLowerCase();
  return ACTIVATION_FUNNEL_KEYS.includes(key) ? key : DEFAULT_ACTIVATION_FUNNEL;
}

/// Breakdown dimensions and where each is read from. Campaign fields prefer the
/// first-class column and fall back to metadata, so rows written before the
/// column hoist still report.
const ACTIVATION_BREAKDOWNS = {
  campaign: "COALESCE(NULLIF(utm_campaign, ''), NULLIF(metadata->>'utm_campaign', ''), '(none)')",
  utm_content: "COALESCE(NULLIF(utm_content, ''), NULLIF(metadata->>'utm_content', ''), '(none)')",
  utm_source: "COALESCE(NULLIF(utm_source, ''), NULLIF(metadata->>'utm_source', ''), '(none)')",
  utm_medium: "COALESCE(NULLIF(utm_medium, ''), NULLIF(metadata->>'utm_medium', ''), '(none)')",
  // Landing surface: `/register` vs `/map` vs anything else. Path only — the
  // client strips the query before sending, so no ad-hoc parameters land here.
  entry_route: "COALESCE(NULLIF(metadata->>'entry_route', ''), '(unknown)')",
  platform: "COALESCE(NULLIF(metadata->>'platform', ''), '(unknown)')",
  locale: "COALESCE(NULLIF(metadata->>'locale', ''), '(unknown)')",
  auth_method: "COALESCE(NULLIF(metadata->>'auth_method', ''), NULLIF(metadata->>'method', ''), '(none)')",
  failure_stage: "COALESCE(NULLIF(metadata->>'failure_stage', ''), '(none)')",
};

const ACTIVATION_BREAKDOWN_KEYS = Object.freeze(Object.keys(ACTIVATION_BREAKDOWNS));

/// Campaign filters. Each prefers the hoisted column and falls back to
/// metadata so rows written before the hoist still match.
const ACTIVATION_FILTERS = {
  utmCampaign: { column: 'utm_campaign', maxLength: 160 },
  utmContent: { column: 'utm_content', maxLength: 128 },
  utmSource: { column: 'utm_source', maxLength: 128 },
  utmMedium: { column: 'utm_medium', maxLength: 128 },
};

const ACTIVATION_FILTER_KEYS = Object.freeze(Object.keys(ACTIVATION_FILTERS));

function normalizeActivationFilter(value, maxLength) {
  const raw = (value === null || value === undefined) ? '' : value.toString().trim();
  if (!raw) return null;
  return raw.slice(0, maxLength);
}

/// Rows returned per breakdown dimension. Bounded so a wide campaign set cannot
/// turn this into an unbounded scan/response.
const ACTIVATION_BREAKDOWN_LIMIT = 25;

function normalizeActivationBreakdown(value) {
  const key = (value || '').toString().trim().toLowerCase();
  return ACTIVATION_BREAKDOWN_KEYS.includes(key) ? key : null;
}

function activationRate(numerator, denominator) {
  if (!denominator) return 0;
  return Math.round((numerator / denominator) * 10000) / 10000;
}

/// Guest -> account activation funnel.
///
/// Returns per-stage session and event counts, stage-to-stage conversion and
/// abandonment, median seconds between the major stages, and bounded
/// breakdowns by campaign, creative, platform, locale, auth method and failure
/// stage.
async function getActivationFunnel({
  property,
  from,
  to,
  ingest = null,
  breakdown = null,
  funnel = null,
  utmCampaign = null,
  utmContent = null,
  utmSource = null,
  utmMedium = null,
}) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const ingestPath = normalizeIngest(ingest);
  const breakdownKey = normalizeActivationBreakdown(breakdown);
  const funnelKey = normalizeActivationFunnel(funnel);
  const definition = ACTIVATION_FUNNELS[funnelKey];
  const stageList = definition.stages;

  const filters = {
    utmCampaign: normalizeActivationFilter(utmCampaign, ACTIVATION_FILTERS.utmCampaign.maxLength),
    utmContent: normalizeActivationFilter(utmContent, ACTIVATION_FILTERS.utmContent.maxLength),
    utmSource: normalizeActivationFilter(utmSource, ACTIVATION_FILTERS.utmSource.maxLength),
    utmMedium: normalizeActivationFilter(utmMedium, ACTIVATION_FILTERS.utmMedium.maxLength),
  };

  // Every filter has to take part in the cache key. `cache.wrap` has a 60s TTL
  // and no invalidation hook, so a missing component would serve one
  // campaign's funnel to another for a full minute.
  const filterKey = ACTIVATION_FILTER_KEYS.map((k) => filters[k] || 'all').join('::');
  const cacheKey = `admin:analytics:app:activation-funnel::${normalizedProperty}::${ingestPath || 'all'}::${funnelKey}::${breakdownKey || 'none'}::${filterKey}::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    const schema = await getAnalyticsEventsSchema();
    if (!schema.exists) throwAnalyticsSchemaError();
    const expr = buildAnalyticsEventsExpr(schema.columns);

    const params = [
      normalizedProperty,
      range.from.toISOString(),
      range.to.toISOString(),
      ingestPath,
      stageList,
    ];

    // Filter predicates live in the shared base CTE so totals, durations and
    // the breakdown are all filtered identically — a filter applied to only
    // some of them would report a campaign's stages against another's medians.
    const filterClauses = [];
    for (const key of ACTIVATION_FILTER_KEYS) {
      const value = filters[key];
      if (!value) continue;
      const { column } = ACTIVATION_FILTERS[key];
      params.push(value);
      const idx = `$${params.length}`;
      // Prefer the hoisted column, fall back to metadata for rows written
      // before the hoist, so historical campaigns stay filterable.
      const source = schema.columns.has(column)
        ? `COALESCE(NULLIF(${column}, ''), NULLIF(metadata->>'${column}', ''))`
        : `NULLIF(metadata->>'${column}', '')`;
      filterClauses.push(`AND ${source} = ${idx}::text`);
    }
    const filterSql = filterClauses.join('\n          ');

    // Direct acquisition is the cohort whose attributed entry event landed on
    // `/register`. Merely having UTMs is insufficient: discovery-map campaigns
    // also carry UTMs through signup and must remain exclusively in the guest
    // funnel. The entry event owns cohort membership; its session join then
    // retains later activation stages even when an older client omitted UTM
    // fields from an individual downstream event.
    const directCohortSql = funnelKey === 'direct_acquisition'
      ? `WHERE EXISTS (
          SELECT 1
          FROM candidate_events entry
          WHERE entry.session_id = candidate.session_id
            AND entry.event_type = 'app_entry'
            AND NULLIF(entry.metadata->>'entry_route', '') = '/register'
            AND (
              COALESCE(NULLIF(entry.utm_campaign, ''), NULLIF(entry.metadata->>'utm_campaign', '')) IS NOT NULL
              OR COALESCE(NULLIF(entry.utm_source, ''), NULLIF(entry.metadata->>'utm_source', '')) IS NOT NULL
              OR COALESCE(NULLIF(entry.utm_medium, ''), NULLIF(entry.metadata->>'utm_medium', '')) IS NOT NULL
              OR COALESCE(NULLIF(entry.utm_content, ''), NULLIF(entry.metadata->>'utm_content', '')) IS NOT NULL
            )
        )`
      : '';

    // One scan feeds every output: per-stage counts, the per-session first-seen
    // timestamps used for durations, and the optional breakdown.
    const baseCte = `
      candidate_events AS (
        SELECT
          event_type,
          ${expr.sessionIdExpr} AS session_id,
          COALESCE(actor_user_id, user_id::text) AS actor_id,
          ${expr.tsExpr} AS event_ts,
          metadata,
          ${schema.columns.has('utm_campaign') ? 'utm_campaign' : "NULL::text AS utm_campaign"},
          ${schema.columns.has('utm_content') ? 'utm_content' : "NULL::text AS utm_content"},
          ${schema.columns.has('utm_source') ? 'utm_source' : "NULL::text AS utm_source"},
          ${schema.columns.has('utm_medium') ? 'utm_medium' : "NULL::text AS utm_medium"}
        FROM public.analytics_events
        WHERE event_category = 'app'
          AND ${expr.propertyExpr} = $1
          AND event_type = ANY($5::text[])
          AND ${expr.tsExpr} >= $2::timestamptz
          AND ${expr.tsExpr} <= $3::timestamptz
          AND ($4::text IS NULL OR ${expr.ingestPathExpr} = $4)
          AND ${expr.eventIdExpr} IS NOT NULL
          AND ${expr.sessionIdExpr} IS NOT NULL
          ${filterSql}
      ),
      base AS (
        SELECT candidate.*
        FROM candidate_events candidate
        ${directCohortSql}
      )`;

    const stageAggregates = stageList.map((stage) => `
        COUNT(*) FILTER (WHERE event_type = '${stage}')::int AS ${stage}_events,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = '${stage}')::int AS ${stage}_sessions,
        COUNT(DISTINCT actor_id) FILTER (WHERE event_type = '${stage}' AND actor_id IS NOT NULL)::int AS ${stage}_users`).join(',');

    const totalsResult = await query(
      `WITH ${baseCte}
       SELECT ${stageAggregates}
       FROM base`,
      params,
    );

    const totalsRow = totalsResult.rows[0] || {};

    // Median seconds between the major transitions, computed per session from
    // each stage's first occurrence. Sessions that never reached the later
    // stage are excluded rather than counted as zero.
    // Each transition is measured from the funnel definition, so the two
    // funnels report the durations that are meaningful to them rather than
    // one hard-coded set. Stages the funnel does not contain resolve to NULL
    // and drop out via the FILTER, exactly as an unreached stage does.
    const durationStages = Array.from(
      new Set(definition.durations.flatMap(([, , fromStage, toStage]) => [fromStage, toStage])),
    );
    const firstsSelect = durationStages
      .map((stage) => `MIN(event_ts) FILTER (WHERE event_type = '${stage}') AS first_${stage}`)
      .join(',\n           ');
    const durationSelect = definition.durations
      .map(([, alias, fromStage, toStage]) => `
         percentile_cont(0.5) WITHIN GROUP (
           ORDER BY EXTRACT(EPOCH FROM (first_${toStage} - first_${fromStage}))
         ) FILTER (WHERE first_${toStage} IS NOT NULL AND first_${fromStage} IS NOT NULL
                     AND first_${toStage} >= first_${fromStage}) AS ${alias}`)
      .join(',');

    const durationsResult = await query(
      `WITH ${baseCte},
       firsts AS (
         SELECT
           session_id,
           ${firstsSelect}
         FROM base
         GROUP BY session_id
       )
       SELECT ${durationSelect}
       FROM firsts`,
      params,
    );

    const durationsRow = durationsResult.rows[0] || {};

    let breakdownRows = [];
    if (breakdownKey) {
      const dimensionExpr = ACTIVATION_BREAKDOWNS[breakdownKey];
      const breakdownEntries = definition.breakdownStages;
      const breakdownSelect = breakdownEntries
        .map(([, alias, stage]) => `COUNT(DISTINCT session_id) FILTER (WHERE event_type = '${stage}')::int AS ${alias}`)
        .join(',\n           ');
      const rateBase = definition.breakdownRateBase;
      const rateBaseAlias = breakdownEntries.find(([key]) => key === rateBase)?.[1];
      const activatedAlias = breakdownEntries.find(([key]) => key === 'activatedSessions')?.[1];
      const breakdownResult = await query(
        `WITH ${baseCte},
         labelled AS (
           SELECT ${dimensionExpr} AS dimension, event_type, session_id
           FROM base
         )
         SELECT
           dimension,
           ${breakdownSelect}
         FROM labelled
         GROUP BY 1
         ORDER BY ${activatedAlias} DESC, ${rateBaseAlias} DESC, dimension ASC
         LIMIT ${ACTIVATION_BREAKDOWN_LIMIT}`,
        params,
      );
      breakdownRows = breakdownResult.rows.map((r) => {
        const row = { dimension: r.dimension || '(none)' };
        for (const [key, alias] of breakdownEntries) row[key] = Number(r[alias] || 0);
        row.activationRate = activationRate(row.activatedSessions, row[rateBase]);
        return row;
      });
    }

    const stages = [];
    let previousSessions = null;
    for (const stage of stageList) {
      const sessions = Number(totalsRow[`${stage}_sessions`] || 0);
      stages.push({
        stage,
        events: Number(totalsRow[`${stage}_events`] || 0),
        sessions,
        uniqueUsers: Number(totalsRow[`${stage}_users`] || 0),
        // Conversion from the immediately preceding stage, plus how many
        // sessions were lost there. Stages are not strictly nested — a session
        // can reach a later stage without emitting an earlier one — so the
        // ratio is clamped to 1 to stay consistent with `abandonedFromPrevious`,
        // which is floored at 0. `rawConversionFromPrevious` keeps the
        // unclamped value so an out-of-order funnel is still diagnosable.
        conversionFromPrevious:
          previousSessions === null ? null : Math.min(1, activationRate(sessions, previousSessions)),
        rawConversionFromPrevious:
          previousSessions === null ? null : activationRate(sessions, previousSessions),
        abandonedFromPrevious:
          previousSessions === null ? null : Math.max(0, previousSessions - sessions),
      });
      previousSessions = sessions;
    }

    const sessionsForStage = (stage) => (
      stage ? (stages.find((s) => s.stage === stage)?.sessions ?? 0) : 0
    );

    const entrySessions = sessionsForStage(definition.entryStage);
    const registeredSessions = sessionsForStage(definition.registeredStage);
    const onboardedSessions = sessionsForStage(definition.onboardedStage);
    // "Activated" is a meaningful platform action, never a view or a login.
    const meaningfullyActivatedSessions = sessionsForStage(definition.activatedStage);
    // Preserved names for the original funnel's consumers: `activatedSessions`
    // has always meant "reached an account session" here, and
    // `completedSessions` "finished the pending action".
    const activatedSessions = funnelKey === DEFAULT_ACTIVATION_FUNNEL
      ? registeredSessions
      : meaningfullyActivatedSessions;
    const completedSessions = funnelKey === DEFAULT_ACTIVATION_FUNNEL
      ? meaningfullyActivatedSessions
      : sessionsForStage(definition.activatedStage);

    // `Number(null)` is 0, so guard explicitly: "no session reached this stage"
    // must report as null, not as an instant median.
    const asSeconds = (value) => {
      if (value === null || value === undefined || value === '') return null;
      const n = Number(value);
      return Number.isFinite(n) ? Math.round(n) : null;
    };

    const medianDurationsSeconds = {};
    for (const [key, alias] of definition.durations) {
      medianDurationsSeconds[key] = asSeconds(durationsRow[alias]);
    }

    return {
      property: normalizedProperty,
      from: range.from.toISOString(),
      to: range.to.toISOString(),
      funnel: funnelKey,
      availableFunnels: ACTIVATION_FUNNEL_KEYS,
      breakdown: breakdownKey,
      availableBreakdowns: ACTIVATION_BREAKDOWN_KEYS,
      // Echoed back so a dashboard can show what it is actually looking at,
      // and so an ignored/normalised filter is visible rather than silent.
      filters,
      stages,
      totals: {
        entrySessions,
        activatedSessions,
        completedSessions,
        activationRate: activationRate(activatedSessions, entrySessions),
        completionRate: activationRate(completedSessions, activatedSessions),
        // Explicit acquisition milestones. Registration alone is not
        // activation, so these are reported separately from the legacy pair
        // above rather than redefining it.
        registeredSessions,
        onboardedSessions,
        meaningfullyActivatedSessions,
        registrationRate: activationRate(registeredSessions, entrySessions),
        onboardingRate: activationRate(onboardedSessions, registeredSessions),
        activatedFromRegisteredRate:
          activationRate(meaningfullyActivatedSessions, registeredSessions),
        activatedFromEntryRate:
          activationRate(meaningfullyActivatedSessions, entrySessions),
      },
      medianDurationsSeconds,
      breakdownRows,
    };
  }, { ttlSeconds: 60 });
}

async function getAppSignInMethods({ property, from, to, ingest = null }) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const ingestPath = normalizeIngest(ingest);

  const types = ['signin_attempt', 'signin_success', 'signin_failure'];

  const cacheKey = `admin:analytics:app:signin-methods::${normalizedProperty}::${ingestPath || 'all'}::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    const schema = await getAnalyticsEventsSchema();
    if (!schema.exists) throwAnalyticsSchemaError();
    const expr = buildAnalyticsEventsExpr(schema.columns);

    const result = await query(
      `WITH base AS (
        SELECT
          event_type,
          COALESCE(NULLIF(trim(lower(metadata->>'method')), ''), 'unknown') AS method,
          ${expr.sessionIdExpr} AS session_id
        FROM public.analytics_events
        WHERE event_category = 'app'
          AND ${expr.propertyExpr} = $1
          AND event_type = ANY($5::text[])
          AND ${expr.tsExpr} >= $2::timestamptz
          AND ${expr.tsExpr} <= $3::timestamptz
          AND ($4::text IS NULL OR ${expr.ingestPathExpr} = $4)
          AND ${expr.eventIdExpr} IS NOT NULL
          AND ${expr.sessionIdExpr} IS NOT NULL
      )
      SELECT
        method,
        COUNT(*) FILTER (WHERE event_type = 'signin_attempt')::int AS attempts,
        COUNT(*) FILTER (WHERE event_type = 'signin_success')::int AS successes,
        COUNT(*) FILTER (WHERE event_type = 'signin_failure')::int AS failures,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'signin_attempt')::int AS attempt_sessions,
        COUNT(DISTINCT session_id) FILTER (WHERE event_type = 'signin_success')::int AS success_sessions
      FROM base
      GROUP BY 1
      ORDER BY attempts DESC, successes DESC`,
      [normalizedProperty, range.from.toISOString(), range.to.toISOString(), ingestPath, types],
    );

    return result.rows.map((r) => {
      const attempts = Number(r.attempts || 0);
      const successes = Number(r.successes || 0);
      return {
        method: r.method || 'unknown',
        attempts,
        successes,
        failures: Number(r.failures || 0),
        attemptSessions: Number(r.attempt_sessions || 0),
        successSessions: Number(r.success_sessions || 0),
        successRate: attempts > 0 ? successes / attempts : null,
      };
    });
  }, { ttlSeconds: 60 });
}

async function getAppScreens({ property, from, to, limit = 25, ingest = null }) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const safeLimit = Math.max(1, Math.min(Number(limit) || 25, 200));
  const ingestPath = normalizeIngest(ingest);

  const cacheKey = `admin:analytics:app:screens::${normalizedProperty}::${ingestPath || 'all'}::${range.from.toISOString()}::${range.to.toISOString()}::${safeLimit}`;

  return cache.wrap(cacheKey, async () => {
    const schema = await getAnalyticsEventsSchema();
    if (!schema.exists) throwAnalyticsSchemaError();
    const expr = buildAnalyticsEventsExpr(schema.columns);

    const result = await query(
      `WITH base AS (
        SELECT
          COALESCE(NULLIF(trim(metadata->>'screen_name'), ''), 'unknown') AS screen_name,
          NULLIF(trim(metadata->>'screen_route'), '') AS screen_route,
          ${expr.sessionIdExpr} AS session_id,
          user_id
        FROM public.analytics_events
        WHERE event_category = 'app'
          AND ${expr.propertyExpr} = $1
          AND event_type = 'screen_view'
          AND ${expr.tsExpr} >= $2::timestamptz
          AND ${expr.tsExpr} <= $3::timestamptz
          AND ($5::text IS NULL OR ${expr.ingestPathExpr} = $5)
          AND ${expr.eventIdExpr} IS NOT NULL
          AND ${expr.sessionIdExpr} IS NOT NULL
      )
      SELECT
        screen_name,
        screen_route,
        COUNT(*)::int AS views,
        COUNT(DISTINCT session_id)::int AS sessions,
        COUNT(DISTINCT user_id)::int AS users
      FROM base
      GROUP BY 1, 2
      ORDER BY views DESC
      LIMIT $4`,
      [normalizedProperty, range.from.toISOString(), range.to.toISOString(), safeLimit, ingestPath],
    );

    return result.rows.map((r) => ({
      screenName: r.screen_name || 'unknown',
      screenRoute: r.screen_route || null,
      views: Number(r.views || 0),
      sessions: Number(r.sessions || 0),
      users: Number(r.users || 0),
    }));
  }, { ttlSeconds: 60 });
}

async function getAppScreenDurations({ property, from, to, limit = 25, ingest = null }) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const safeLimit = Math.max(1, Math.min(Number(limit) || 25, 200));
  const ingestPath = normalizeIngest(ingest);

  const cacheKey = `admin:analytics:app:screen-durations::${normalizedProperty}::${ingestPath || 'all'}::${range.from.toISOString()}::${range.to.toISOString()}::${safeLimit}`;

  return cache.wrap(cacheKey, async () => {
    const schema = await getAnalyticsEventsSchema();
    if (!schema.exists) throwAnalyticsSchemaError();
    const expr = buildAnalyticsEventsExpr(schema.columns);

    const durationExpr = `CASE WHEN (metadata->>'duration_ms') ~ '^[0-9]+$' THEN (metadata->>'duration_ms')::int ELSE NULL END`;

    const baseWhere = `event_category = 'app'
      AND ${expr.propertyExpr} = $1
      AND event_type = 'screen_duration'
      AND ${expr.tsExpr} >= $2::timestamptz
      AND ${expr.tsExpr} <= $3::timestamptz
      AND ($4::text IS NULL OR ${expr.ingestPathExpr} = $4)
      AND ${expr.eventIdExpr} IS NOT NULL
      AND ${expr.sessionIdExpr} IS NOT NULL`;

    const [byScreen, overall, histogram] = await Promise.all([
      query(
        `WITH base AS (
          SELECT
            COALESCE(NULLIF(trim(metadata->>'screen_name'), ''), 'unknown') AS screen_name,
            NULLIF(trim(metadata->>'screen_route'), '') AS screen_route,
            ${durationExpr} AS duration_ms
          FROM public.analytics_events
          WHERE ${baseWhere}
        )
        SELECT
          screen_name,
          screen_route,
          COUNT(*) FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0)::int AS samples,
          ROUND(AVG(duration_ms) FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0))::int AS avg_duration_ms,
          ROUND(
            percentile_cont(0.50) WITHIN GROUP (ORDER BY duration_ms)
            FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0)
          )::int AS p50_duration_ms,
          ROUND(
            percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms)
            FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0)
          )::int AS p95_duration_ms
        FROM base
        GROUP BY 1, 2
        HAVING COUNT(*) FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0) > 0
        ORDER BY samples DESC
        LIMIT $5`,
        [normalizedProperty, range.from.toISOString(), range.to.toISOString(), ingestPath, safeLimit],
      ),
      query(
        `WITH base AS (
          SELECT
            ${durationExpr} AS duration_ms
          FROM public.analytics_events
          WHERE ${baseWhere}
        )
        SELECT
          COUNT(*) FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0)::int AS samples,
          ROUND(AVG(duration_ms) FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0))::int AS avg_duration_ms,
          ROUND(
            percentile_cont(0.50) WITHIN GROUP (ORDER BY duration_ms)
            FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0)
          )::int AS p50_duration_ms,
          ROUND(
            percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms)
            FILTER (WHERE duration_ms IS NOT NULL AND duration_ms > 0)
          )::int AS p95_duration_ms
        FROM base`,
        [normalizedProperty, range.from.toISOString(), range.to.toISOString(), ingestPath],
      ),
      query(
        `WITH base AS (
          SELECT
            ${durationExpr} AS duration_ms
          FROM public.analytics_events
          WHERE ${baseWhere}
        ), buckets AS (
          SELECT
            CASE
              WHEN duration_ms < 5000 THEN '0-5s'
              WHEN duration_ms < 15000 THEN '5-15s'
              WHEN duration_ms < 30000 THEN '15-30s'
              WHEN duration_ms < 60000 THEN '30-60s'
              WHEN duration_ms < 120000 THEN '60-120s'
              WHEN duration_ms < 300000 THEN '120-300s'
              ELSE '300s+'
            END AS bucket
          FROM base
          WHERE duration_ms IS NOT NULL AND duration_ms > 0
        )
        SELECT
          bucket,
          COUNT(*)::int AS samples
        FROM buckets
        GROUP BY 1
        ORDER BY
          CASE bucket
            WHEN '0-5s' THEN 1
            WHEN '5-15s' THEN 2
            WHEN '15-30s' THEN 3
            WHEN '30-60s' THEN 4
            WHEN '60-120s' THEN 5
            WHEN '120-300s' THEN 6
            ELSE 7
          END`,
        [normalizedProperty, range.from.toISOString(), range.to.toISOString(), ingestPath],
      ),
    ]);

    const overallRow = overall.rows[0] || {};

    return {
      property: normalizedProperty,
      from: range.from.toISOString(),
      to: range.to.toISOString(),
      overall: {
        samples: Number(overallRow.samples || 0),
        avgDurationMs: overallRow.avg_duration_ms ?? null,
        p50DurationMs: overallRow.p50_duration_ms ?? null,
        p95DurationMs: overallRow.p95_duration_ms ?? null,
      },
      byScreen: byScreen.rows.map((r) => ({
        screenName: r.screen_name || 'unknown',
        screenRoute: r.screen_route || null,
        samples: Number(r.samples || 0),
        avgDurationMs: r.avg_duration_ms ?? null,
        p50DurationMs: r.p50_duration_ms ?? null,
        p95DurationMs: r.p95_duration_ms ?? null,
      })),
      histogram: histogram.rows.map((r) => ({
        bucket: r.bucket,
        samples: Number(r.samples || 0),
      })),
    };
  }, { ttlSeconds: 90 });
}

/// How far before the reported range the "first seen" scans may look.
///
/// These bounds are what keep retention runnable. Both scans previously had no
/// time predicate at all -- they read every `event_category = 'app'` row ever
/// written on each request -- so as telemetry grew the query crossed the 15s
/// `statement_timeout` and the endpoint started returning 500s.
///
/// Bounding is safe because the scans only exist to classify new vs returning
/// *inside* the reported range. For any day D in the range:
///   - a first event inside the range is measured exactly, and
///   - a first event anywhere before `from` makes the row returning for every
///     day in the range, regardless of how much earlier it actually was.
/// So the lookback only has to be long enough to notice that earlier activity
/// exists at all.
///
/// Sessions rotate every six hours (`AppTelemetryConfig.sessionRotation`), so a
/// session cannot meaningfully predate the range by more than that; a week is
/// already far past generous. Users need a real window, since "returning user"
/// is a genuine all-time property -- a year covers any active account, and a
/// user with no activity for over a year reads as new, which is the more useful
/// reading of a reactivation anyway.
const SESSION_FIRST_SEEN_LOOKBACK_DAYS = 7;
const USER_FIRST_SEEN_LOOKBACK_DAYS = 365;

async function getAppRetention({ property, from, to, ingest = null }) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const ingestPath = normalizeIngest(ingest);

  const cacheKey = `admin:analytics:app:retention::${normalizedProperty}::${ingestPath || 'all'}::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    const schema = await getAnalyticsEventsSchema();
    if (!schema.exists) throwAnalyticsSchemaError();
    const hasTs = schema.columns.has('ts');
    const hasProperty = schema.columns.has('property');
    const hasSessionId = schema.columns.has('session_id');
    const hasEventId = schema.columns.has('event_id');
    const hasIngestPath = schema.columns.has('ingest_path');
    const hasActorUserId = schema.columns.has('actor_user_id');

    // Fast-path for the modern schema: avoids COALESCE expressions in WHERE clauses so indexes can be used.
    if (hasProperty && hasTs && hasSessionId && hasEventId) {
      const tsValueExpr = hasTs ? `ts` : `created_at`;
      const tsBucketExpr = hasTs ? `COALESCE(ts, created_at)` : `created_at`;
      const tsRangeWhere = hasTs
        ? `((ts >= $2::timestamptz AND ts <= $3::timestamptz) OR (ts IS NULL AND created_at >= $2::timestamptz AND created_at <= $3::timestamptz))`
        : `(created_at >= $2::timestamptz AND created_at <= $3::timestamptz)`;

      const propertyWhere = hasProperty
        ? `(property = $1 OR (property IS NULL AND (metadata->>'property') = $1))`
        : `(metadata->>'property') = $1`;

      const sessionIdValueExpr = hasSessionId ? `NULLIF(session_id::text, '')` : `NULLIF(metadata->>'session_id', '')`;
      const ingestWhere = hasIngestPath
        ? `($4::text IS NULL OR COALESCE(NULLIF(trim(ingest_path::text), ''), 'server') = $4)`
        : `($4::text IS NULL OR COALESCE(NULLIF(trim(metadata->>'ingest_path'), ''), 'server') = $4)`;
      const eventIdWhere = hasEventId ? `event_id IS NOT NULL` : `NULLIF(metadata->>'event_id', '') IS NOT NULL`;

      const userKeyExpr = hasActorUserId
        ? `NULLIF(actor_user_id::text, '')`
        : schema.columns.has('user_id')
          ? `user_id::text`
          : `NULLIF(metadata->>'actor_user_id', '')`;

      const dayExpr = `(date_trunc('day', (${tsBucketExpr} AT TIME ZONE 'UTC')) AT TIME ZONE 'UTC')`;

      const result = await query(
        `WITH range_events AS (
          SELECT
            ${dayExpr} AS day,
            ${sessionIdValueExpr} AS session_id,
            ${userKeyExpr} AS user_key,
            ${tsBucketExpr} AS ts
          FROM public.analytics_events
          WHERE event_category = 'app'
            AND ${propertyWhere}
            AND ${tsRangeWhere}
            AND ${ingestWhere}
            AND ${eventIdWhere}
            AND ${sessionIdValueExpr} IS NOT NULL
        ),
        range_sessions AS (
          SELECT DISTINCT session_id
          FROM range_events
        ),
        session_first AS (
          SELECT
            ${sessionIdValueExpr} AS session_id,
            MIN(${tsValueExpr}) AS first_ts
          FROM public.analytics_events
          WHERE event_category = 'app'
            AND ${propertyWhere}
            AND ${ingestWhere}
            AND ${eventIdWhere}
            AND ${sessionIdValueExpr} IS NOT NULL
            AND ${sessionIdValueExpr} IN (SELECT session_id FROM range_sessions)
            AND ${tsValueExpr} >= ($2::timestamptz - interval '${SESSION_FIRST_SEEN_LOOKBACK_DAYS} days')
            AND ${tsValueExpr} <= $3::timestamptz
          GROUP BY 1
        ),
        day_sessions AS (
          SELECT
            day,
            session_id,
            MAX(user_key) FILTER (WHERE user_key IS NOT NULL) AS any_user_key
          FROM range_events
          GROUP BY 1, 2
        ),
        session_metrics AS (
          SELECT
            ds.day AS bucket,
            COUNT(DISTINCT ds.session_id)::int AS sessions,
            COUNT(DISTINCT ds.session_id) FILTER (WHERE sf.first_ts >= ds.day AND sf.first_ts < ds.day + interval '1 day')::int AS new_sessions,
            COUNT(DISTINCT ds.session_id) FILTER (WHERE sf.first_ts < ds.day)::int AS returning_sessions,
            COUNT(DISTINCT ds.session_id) FILTER (WHERE ds.any_user_key IS NULL)::int AS anonymous_sessions
          FROM day_sessions ds
          LEFT JOIN session_first sf ON sf.session_id = ds.session_id
          GROUP BY 1
        ),
        range_users AS (
          SELECT DISTINCT user_key
          FROM range_events
          WHERE user_key IS NOT NULL
        ),
        user_first AS (
          SELECT
            ${userKeyExpr} AS user_key,
            MIN(${tsValueExpr}) AS first_ts
          FROM public.analytics_events
          WHERE event_category = 'app'
            AND ${propertyWhere}
            AND ${ingestWhere}
            AND ${eventIdWhere}
            AND ${userKeyExpr} IS NOT NULL
            AND ${userKeyExpr} IN (SELECT user_key FROM range_users)
            AND ${tsValueExpr} >= ($2::timestamptz - interval '${USER_FIRST_SEEN_LOOKBACK_DAYS} days')
            AND ${tsValueExpr} <= $3::timestamptz
          GROUP BY 1
        ),
        day_users AS (
          SELECT
            day,
            user_key
          FROM range_events
          WHERE user_key IS NOT NULL
          GROUP BY 1, 2
        ),
        user_metrics AS (
          SELECT
            du.day AS bucket,
            COUNT(DISTINCT du.user_key)::int AS users,
            COUNT(DISTINCT du.user_key) FILTER (WHERE uf.first_ts >= du.day AND uf.first_ts < du.day + interval '1 day')::int AS new_users,
            COUNT(DISTINCT du.user_key) FILTER (WHERE uf.first_ts < du.day)::int AS returning_users
          FROM day_users du
          LEFT JOIN user_first uf ON uf.user_key = du.user_key
          GROUP BY 1
        )
        SELECT
          COALESCE(sm.bucket, um.bucket) AS bucket,
          COALESCE(sm.sessions, 0)::int AS sessions,
          COALESCE(sm.new_sessions, 0)::int AS new_sessions,
          COALESCE(sm.returning_sessions, 0)::int AS returning_sessions,
          COALESCE(sm.anonymous_sessions, 0)::int AS anonymous_sessions,
          COALESCE(um.users, 0)::int AS users,
          COALESCE(um.new_users, 0)::int AS new_users,
          COALESCE(um.returning_users, 0)::int AS returning_users
        FROM session_metrics sm
        FULL OUTER JOIN user_metrics um ON um.bucket = sm.bucket
        ORDER BY 1`,
        [normalizedProperty, range.from.toISOString(), range.to.toISOString(), ingestPath],
      );

      return {
        property: normalizedProperty,
        from: range.from.toISOString(),
        to: range.to.toISOString(),
        series: result.rows.map((r) => ({
          bucket: r.bucket,
          sessions: Number(r.sessions || 0),
          newSessions: Number(r.new_sessions || 0),
          returningSessions: Number(r.returning_sessions || 0),
          anonymousSessions: Number(r.anonymous_sessions || 0),
          users: Number(r.users || 0),
          newUsers: Number(r.new_users || 0),
          returningUsers: Number(r.returning_users || 0),
        })),
      };
    }

    // Fallback for older schemas: relies on metadata where needed.
    const expr = buildAnalyticsEventsExpr(schema.columns);
    const dayExpr = `(date_trunc('day', (${expr.tsExpr} AT TIME ZONE 'UTC')) AT TIME ZONE 'UTC')`;

    const result = await query(
      `WITH range_events AS (
        SELECT
          ${dayExpr} AS day,
          ${expr.sessionIdExpr} AS session_id,
          user_id,
          ${expr.tsExpr} AS ts
        FROM public.analytics_events
        WHERE event_category = 'app'
          AND ${expr.propertyExpr} = $1
          AND ${expr.tsExpr} >= $2::timestamptz
          AND ${expr.tsExpr} <= $3::timestamptz
          AND ($4::text IS NULL OR ${expr.ingestPathExpr} = $4)
          AND ${expr.eventIdExpr} IS NOT NULL
          AND ${expr.sessionIdExpr} IS NOT NULL
      ),
      range_sessions AS (
        SELECT DISTINCT session_id
        FROM range_events
      ),
      session_first AS (
        SELECT
          ${expr.sessionIdExpr} AS session_id,
          MIN(${expr.tsExpr}) AS first_ts
        FROM public.analytics_events
        WHERE event_category = 'app'
          AND ${expr.propertyExpr} = $1
          AND ($4::text IS NULL OR ${expr.ingestPathExpr} = $4)
          AND ${expr.eventIdExpr} IS NOT NULL
          AND ${expr.sessionIdExpr} IS NOT NULL
          AND ${expr.sessionIdExpr} IN (SELECT session_id FROM range_sessions)
          AND ${expr.tsExpr} >= ($2::timestamptz - interval '${SESSION_FIRST_SEEN_LOOKBACK_DAYS} days')
          AND ${expr.tsExpr} <= $3::timestamptz
        GROUP BY 1
      ),
      day_sessions AS (
        SELECT
          day,
          session_id,
          MAX(user_id) FILTER (WHERE user_id IS NOT NULL) AS any_user_id
        FROM range_events
        GROUP BY 1, 2
      ),
      session_metrics AS (
        SELECT
          ds.day AS bucket,
          COUNT(DISTINCT ds.session_id)::int AS sessions,
          COUNT(DISTINCT ds.session_id) FILTER (WHERE sf.first_ts >= ds.day AND sf.first_ts < ds.day + interval '1 day')::int AS new_sessions,
          COUNT(DISTINCT ds.session_id) FILTER (WHERE sf.first_ts < ds.day)::int AS returning_sessions,
          COUNT(DISTINCT ds.session_id) FILTER (WHERE ds.any_user_id IS NULL)::int AS anonymous_sessions
        FROM day_sessions ds
        LEFT JOIN session_first sf ON sf.session_id = ds.session_id
        GROUP BY 1
      ),
      range_users AS (
        SELECT DISTINCT user_id
        FROM range_events
        WHERE user_id IS NOT NULL
      ),
      user_first AS (
        SELECT
          user_id,
          MIN(${expr.tsExpr}) AS first_ts
        FROM public.analytics_events
        WHERE event_category = 'app'
          AND ${expr.propertyExpr} = $1
          AND ($4::text IS NULL OR ${expr.ingestPathExpr} = $4)
          AND ${expr.eventIdExpr} IS NOT NULL
          AND user_id IS NOT NULL
          AND user_id IN (SELECT user_id FROM range_users)
          AND ${expr.tsExpr} >= ($2::timestamptz - interval '${USER_FIRST_SEEN_LOOKBACK_DAYS} days')
          AND ${expr.tsExpr} <= $3::timestamptz
        GROUP BY 1
      ),
      day_users AS (
        SELECT
          day,
          user_id
        FROM range_events
        WHERE user_id IS NOT NULL
        GROUP BY 1, 2
      ),
      user_metrics AS (
        SELECT
          du.day AS bucket,
          COUNT(DISTINCT du.user_id)::int AS users,
          COUNT(DISTINCT du.user_id) FILTER (WHERE uf.first_ts >= du.day AND uf.first_ts < du.day + interval '1 day')::int AS new_users,
          COUNT(DISTINCT du.user_id) FILTER (WHERE uf.first_ts < du.day)::int AS returning_users
        FROM day_users du
        LEFT JOIN user_first uf ON uf.user_id = du.user_id
        GROUP BY 1
      )
      SELECT
        COALESCE(sm.bucket, um.bucket) AS bucket,
        COALESCE(sm.sessions, 0)::int AS sessions,
        COALESCE(sm.new_sessions, 0)::int AS new_sessions,
        COALESCE(sm.returning_sessions, 0)::int AS returning_sessions,
        COALESCE(sm.anonymous_sessions, 0)::int AS anonymous_sessions,
        COALESCE(um.users, 0)::int AS users,
        COALESCE(um.new_users, 0)::int AS new_users,
        COALESCE(um.returning_users, 0)::int AS returning_users
      FROM session_metrics sm
      FULL OUTER JOIN user_metrics um ON um.bucket = sm.bucket
      ORDER BY 1`,
      [normalizedProperty, range.from.toISOString(), range.to.toISOString(), ingestPath],
    );

    return {
      property: normalizedProperty,
      from: range.from.toISOString(),
      to: range.to.toISOString(),
      series: result.rows.map((r) => ({
        bucket: r.bucket,
        sessions: Number(r.sessions || 0),
        newSessions: Number(r.new_sessions || 0),
        returningSessions: Number(r.returning_sessions || 0),
        anonymousSessions: Number(r.anonymous_sessions || 0),
        users: Number(r.users || 0),
        newUsers: Number(r.new_users || 0),
        returningUsers: Number(r.returning_users || 0),
      })),
    };
  }, { ttlSeconds: 90 });
}

async function getApiTelemetryOverview({ property, from, to, ingest = null }) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const ingestPath = normalizeIngest(ingest);

  const cacheKey = `admin:analytics:app:api:overview::${normalizedProperty}::${ingestPath || 'all'}::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    const result = await query(
      `SELECT
        COUNT(*)::int AS requests,
        COUNT(*) FILTER (WHERE status_code >= 400)::int AS errors,
        ROUND(AVG(latency_ms) FILTER (WHERE latency_ms IS NOT NULL))::int AS avg_latency_ms,
        ROUND(
          percentile_cont(0.50) WITHIN GROUP (ORDER BY latency_ms)
          FILTER (WHERE latency_ms IS NOT NULL)
        )::int AS p50_latency_ms,
        ROUND(
          percentile_cont(0.95) WITHIN GROUP (ORDER BY latency_ms)
          FILTER (WHERE latency_ms IS NOT NULL)
        )::int AS p95_latency_ms
       FROM public.analytics_events
       WHERE event_category = 'app'
          AND event_type = 'api_request'
          AND COALESCE(property, (metadata->>'property')) = $1
          AND COALESCE(ts, created_at) >= $2::timestamptz
          AND COALESCE(ts, created_at) <= $3::timestamptz
          AND ($4::text IS NULL OR COALESCE(ingest_path, 'server') = $4)`,
      [normalizedProperty, range.from.toISOString(), range.to.toISOString(), ingestPath],
    );

    const row = result.rows[0] || {};
    const requests = row.requests || 0;
    const errors = row.errors || 0;
    const errorRate = requests > 0 ? errors / requests : 0;

    return {
      property: normalizedProperty,
      from: range.from.toISOString(),
      to: range.to.toISOString(),
      requests,
      errors,
      errorRate,
      avgLatencyMs: row.avg_latency_ms || 0,
      p50LatencyMs: row.p50_latency_ms || 0,
      p95LatencyMs: row.p95_latency_ms || 0,
    };
  }, { ttlSeconds: 30 });
}

async function getApiTelemetryTopRouteGroups({ property, from, to, limit = 25, ingest = null }) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const safeLimit = Math.max(1, Math.min(Number(limit) || 25, 200));
  const ingestPath = normalizeIngest(ingest);

  const result = await query(
    `SELECT
      COALESCE(NULLIF(trim(metadata->>'route_group'), ''), 'unknown') AS route_group,
      COUNT(*)::int AS requests,
      COUNT(*) FILTER (WHERE status_code >= 400)::int AS errors,
      ROUND(AVG(latency_ms) FILTER (WHERE latency_ms IS NOT NULL))::int AS avg_latency_ms,
      ROUND(
        percentile_cont(0.95) WITHIN GROUP (ORDER BY latency_ms)
        FILTER (WHERE latency_ms IS NOT NULL)
      )::int AS p95_latency_ms
     FROM public.analytics_events
     WHERE event_category = 'app'
       AND event_type = 'api_request'
       AND COALESCE(property, (metadata->>'property')) = $1
       AND COALESCE(ts, created_at) >= $2::timestamptz
        AND COALESCE(ts, created_at) <= $3::timestamptz
        AND ($5::text IS NULL OR COALESCE(ingest_path, 'server') = $5)
     GROUP BY 1
     ORDER BY requests DESC
     LIMIT $4`,
    [normalizedProperty, range.from.toISOString(), range.to.toISOString(), safeLimit, ingestPath],
  );

  return result.rows.map((r) => ({
    routeGroup: r.route_group,
    requests: r.requests || 0,
    errors: r.errors || 0,
    avgLatencyMs: r.avg_latency_ms || 0,
    p95LatencyMs: r.p95_latency_ms || 0,
  }));
}

async function getApiTelemetryLatencySeries({ property, from, to, bucket = 'hour', routeGroup = null, ingest = null }) {
  const normalizedProperty = normalizeProperty(property);
  const range = parseRange({ from, to });
  const ingestPath = normalizeIngest(ingest);

  const safeBucket = (bucket || '').toString().trim();
  const allowedBuckets = new Set(['hour', 'day', 'week']);
  if (!allowedBuckets.has(safeBucket)) {
    const error = new Error('Invalid bucket');
    error.statusCode = 400;
    throw error;
  }

  const safeRouteGroup = routeGroup ? (routeGroup || '').toString().trim() : null;

  const cacheKey = `admin:analytics:app:api:latency-series::${normalizedProperty}::${ingestPath || 'all'}::${safeRouteGroup || 'all'}::${safeBucket}::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    const result = await query(
      `SELECT
        (date_trunc('${safeBucket}', (COALESCE(ts, created_at) AT TIME ZONE 'UTC')) AT TIME ZONE 'UTC') AS bucket,
        COUNT(*)::int AS requests,
        COUNT(*) FILTER (WHERE status_code >= 400)::int AS errors,
        ROUND(AVG(latency_ms) FILTER (WHERE latency_ms IS NOT NULL))::int AS avg_latency_ms,
        ROUND(
          percentile_cont(0.95) WITHIN GROUP (ORDER BY latency_ms)
          FILTER (WHERE latency_ms IS NOT NULL)
        )::int AS p95_latency_ms
       FROM public.analytics_events
       WHERE event_category = 'app'
          AND event_type = 'api_request'
          AND COALESCE(property, (metadata->>'property')) = $1
          AND ($2::text IS NULL OR COALESCE(NULLIF(trim(metadata->>'route_group'), ''), 'unknown') = $2)
          AND COALESCE(ts, created_at) >= $3::timestamptz
          AND COALESCE(ts, created_at) <= $4::timestamptz
          AND ($5::text IS NULL OR COALESCE(ingest_path, 'server') = $5)
        GROUP BY 1
        ORDER BY 1`,
      [normalizedProperty, safeRouteGroup, range.from.toISOString(), range.to.toISOString(), ingestPath],
    );

    return result.rows.map((r) => ({
      bucket: r.bucket,
      requests: r.requests || 0,
      errors: r.errors || 0,
      avgLatencyMs: r.avg_latency_ms || 0,
      p95LatencyMs: r.p95_latency_ms || 0,
    }));
  }, { ttlSeconds: 30 });
}

/**
 * App dashboard stats: platform totals + growth within the selected period.
 * Returns users, groups, artworks, posts, collections, and new items in range.
 */
async function getAppDashboardStats({ from, to }) {
  const range = parseRange({ from, to });

  const cacheKey = `admin:analytics:app:dashboard::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    // Run all queries in parallel
    const [
      totalsResult,
      newUsersResult,
      newGroupsResult,
      newArtworksResult,
      newPostsResult,
      newCollectionsResult,
      activityResult,
    ] = await Promise.all([
      // Platform totals
      query(`
        SELECT
          (SELECT COUNT(*)::int FROM users) AS total_users,
          (SELECT COUNT(*)::int FROM profiles) AS total_profiles,
          (SELECT COUNT(*)::int FROM groups WHERE is_public = true) AS total_groups,
          (SELECT COUNT(*)::int FROM artworks WHERE is_active = true AND is_public = true) AS total_artworks,
          (SELECT COUNT(*)::int FROM artworks WHERE is_active = true AND is_public = true AND is_ar_enabled = true) AS ar_enabled_artworks,
          (SELECT COUNT(*)::int FROM community_posts WHERE is_active = true AND is_public = true) AS total_posts,
          (SELECT COUNT(*)::int FROM collections) AS total_collections
      `),
      // New users in range
      query(`
        SELECT COUNT(*)::int AS count
        FROM users
        WHERE created_at >= $1::timestamptz AND created_at <= $2::timestamptz
      `, [range.from.toISOString(), range.to.toISOString()]),
      // New groups in range
      query(`
        SELECT COUNT(*)::int AS count
        FROM groups
        WHERE is_public = true
          AND created_at >= $1::timestamptz AND created_at <= $2::timestamptz
      `, [range.from.toISOString(), range.to.toISOString()]),
      // New artworks in range
      query(`
        SELECT COUNT(*)::int AS count
        FROM artworks
        WHERE is_active = true AND is_public = true
          AND created_at >= $1::timestamptz AND created_at <= $2::timestamptz
      `, [range.from.toISOString(), range.to.toISOString()]),
      // New posts in range
      query(`
        SELECT COUNT(*)::int AS count
        FROM community_posts
        WHERE is_active = true AND is_public = true
          AND created_at >= $1::timestamptz AND created_at <= $2::timestamptz
      `, [range.from.toISOString(), range.to.toISOString()]),
      // New collections in range
      query(`
        SELECT COUNT(*)::int AS count
        FROM collections
        WHERE created_at >= $1::timestamptz AND created_at <= $2::timestamptz
      `, [range.from.toISOString(), range.to.toISOString()]),
      // Activity in range (likes, follows, views)
      query(`
        SELECT
          (SELECT COUNT(*)::int FROM likes WHERE created_at >= $1::timestamptz AND created_at <= $2::timestamptz) AS new_likes,
          (SELECT COUNT(*)::int FROM follows WHERE created_at >= $1::timestamptz AND created_at <= $2::timestamptz) AS new_follows,
          (SELECT COUNT(*)::int FROM analytics_events WHERE event_type = 'view' AND COALESCE(ts, created_at) >= $1::timestamptz AND COALESCE(ts, created_at) <= $2::timestamptz) AS new_views
      `, [range.from.toISOString(), range.to.toISOString()]),
    ]);

    const totals = totalsResult.rows[0] || {};
    const activity = activityResult.rows[0] || {};

    return {
      from: range.from.toISOString(),
      to: range.to.toISOString(),
      // Totals
      totalUsers: totals.total_users || 0,
      totalProfiles: totals.total_profiles || 0,
      totalGroups: totals.total_groups || 0,
      totalArtworks: totals.total_artworks || 0,
      arEnabledArtworks: totals.ar_enabled_artworks || 0,
      totalPosts: totals.total_posts || 0,
      totalCollections: totals.total_collections || 0,
      // Growth in period
      newUsers: newUsersResult.rows[0]?.count || 0,
      newGroups: newGroupsResult.rows[0]?.count || 0,
      newArtworks: newArtworksResult.rows[0]?.count || 0,
      newPosts: newPostsResult.rows[0]?.count || 0,
      newCollections: newCollectionsResult.rows[0]?.count || 0,
      // Activity in period
      newLikes: activity.new_likes || 0,
      newFollows: activity.new_follows || 0,
      newViews: activity.new_views || 0,
    };
  }, { ttlSeconds: 60 });
}

/**
 * Growth time series for a specific entity type (users, artworks, posts, groups).
 */
async function getAppGrowthSeries({ entityType = 'users', from, to, bucket = 'day' }) {
  const range = parseRange({ from, to });

  const safeBucket = (bucket || '').toString().trim();
  const allowedBuckets = new Set(['hour', 'day', 'week']);
  if (!allowedBuckets.has(safeBucket)) {
    const error = new Error('Invalid bucket');
    error.statusCode = 400;
    throw error;
  }

  const safeEntityType = (entityType || '').toString().trim().toLowerCase();
  const tableMap = {
    users: { table: 'users', condition: '' },
    artworks: { table: 'artworks', condition: 'AND is_active = true AND is_public = true' },
    posts: { table: 'community_posts', condition: 'AND is_active = true AND is_public = true' },
    groups: { table: 'groups', condition: 'AND is_public = true' },
    collections: { table: 'collections', condition: '' },
  };

  if (!tableMap[safeEntityType]) {
    const error = new Error('Invalid entityType');
    error.statusCode = 400;
    throw error;
  }

  const { table, condition } = tableMap[safeEntityType];

  const cacheKey = `admin:analytics:app:growth-series::${safeEntityType}::${safeBucket}::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    const result = await query(
      `SELECT
        (date_trunc('${safeBucket}', (created_at AT TIME ZONE 'UTC')) AT TIME ZONE 'UTC') AS bucket,
        COUNT(*)::int AS value
       FROM ${table}
       WHERE created_at >= $1::timestamptz
         AND created_at <= $2::timestamptz
         ${condition}
       GROUP BY 1
       ORDER BY 1`,
      [range.from.toISOString(), range.to.toISOString()],
    );

    return result.rows.map((r) => ({ bucket: r.bucket, value: r.value }));
  }, { ttlSeconds: 60 });
}

async function getIngestBreakdown({ property, from, to, category = 'web' }) {
  const safeCategory = (category || '').toString().trim().toLowerCase();
  const allowed = new Set(['web', 'app', 'diag']);
  if (!allowed.has(safeCategory)) {
    const error = new Error('Invalid category');
    error.statusCode = 400;
    throw error;
  }

  // "web" uses site values (kubus.site, art.kubus.site); "app"/"diag" use app properties (app.kubus.site, api.kubus.site, bapi.kubus.site).
  const normalizedProperty = safeCategory === 'web' ? normalizeSite(property) : normalizeProperty(property);
  const range = parseRange({ from, to });

  const cacheKey = `admin:analytics:ingest-breakdown::${safeCategory}::${normalizedProperty}::${range.from.toISOString()}::${range.to.toISOString()}`;

  return cache.wrap(cacheKey, async () => {
    const schema = await getAnalyticsEventsSchema();
    if (!schema.exists) throwAnalyticsSchemaError();
    const expr = buildAnalyticsEventsExpr(schema.columns);

    const whereProperty = `${expr.propertyExpr} = $1`;
    const ingestGroupExpr = schema.columns.has('ingest_path')
      ? `COALESCE(NULLIF(trim(ingest_path), ''), 'unknown')`
      : `COALESCE(NULLIF(trim(metadata->>'ingest_path'), ''), 'unknown')`;

    const trustedWebOnly = safeCategory === 'web'
      ? `AND ${expr.eventIdExpr} IS NOT NULL
         AND ${expr.sessionIdExpr} IS NOT NULL`
      : '';

    const result = await query(
      `SELECT
        ${ingestGroupExpr} AS ingest_path,
        COUNT(*)::int AS events,
        COUNT(*) FILTER (WHERE ${expr.ingestFallbackExpr} = true)::int AS fallback_events
       FROM public.analytics_events
       WHERE event_category = $2
         AND ${whereProperty}
         AND ${expr.tsExpr} >= $3::timestamptz
         AND ${expr.tsExpr} <= $4::timestamptz
         ${trustedWebOnly}
       GROUP BY 1
       ORDER BY events DESC`,
      [normalizedProperty, safeCategory, range.from.toISOString(), range.to.toISOString()],
    );

    const byIngest = {};
    let totalEvents = 0;
    let totalFallbackEvents = 0;
    for (const row of result.rows) {
      const key = row.ingest_path || 'unknown';
      const n = Number(row.events || 0);
      const f = Number(row.fallback_events || 0);
      byIngest[key] = n;
      totalEvents += n;
      totalFallbackEvents += f;
    }

    const fallbackRate = totalEvents > 0 ? totalFallbackEvents / totalEvents : 0;

    return {
      property: normalizedProperty,
      category: safeCategory,
      from: range.from.toISOString(),
      to: range.to.toISOString(),
      byIngest,
      totalEvents,
      fallbackEvents: totalFallbackEvents,
      fallbackRate,
    };
  }, { ttlSeconds: 30 });
}

